import type { Tools } from "../generated/tools";

interface IndexedModule {
  path: string;
  lines: number;
  exports: string[];
}

interface Failure {
  path: string;
  reason: string;
}

function parseSearchHits(content: string): string[] {
  return content
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.endsWith(".ts"));
}

function takeFirst(paths: string[], max: number): string[] {
  return paths.slice(0, Math.max(0, max));
}

function countLines(content: string): number {
  return content.split("\n").length;
}

function extractExportedNames(source: string): string[] {
  const names = new Set<string>();
  const declarations =
    /\bexport\s+(?:declare\s+)?(?:default\s+)?(?:async\s+)?(?:function\s*\*?|class|const|let|var|interface|type|enum)\s+([A-Za-z0-9_$]+)/g;
  const braceLists = /\bexport\s*\{([^}]*)\}/g;
  const starReexports =
    /\bexport\s*\*\s*(?:as\s+[A-Za-z0-9_$]+\s*)?from\s*["']([^"']+)["']/g;

  for (const match of source.matchAll(declarations)) {
    names.add(match[1]);
  }
  for (const match of source.matchAll(braceLists)) {
    for (const part of match[1].split(",")) {
      const name = part.trim().split(/\s+as\s+/)[0].trim();
      if (name.length > 0) {
        names.add(name);
      }
    }
  }
  for (const match of source.matchAll(starReexports)) {
    names.add(`* from "${match[1]}"`);
  }
  return Array.from(names);
}

function summarizeModule(path: string, content: string): IndexedModule {
  return {
    path,
    lines: countLines(content),
    exports: extractExportedNames(content),
  };
}

function moduleObservations(entry: IndexedModule): string[] {
  const exportLine =
    entry.exports.length > 0 ? entry.exports.join(", ") : "none";
  return [`${entry.lines} lines`, `exports: ${exportLine}`];
}

function recordIndexed(indexed: IndexedModule[], entry: IndexedModule) {
  indexed.push(entry);
}

function recordFailure(failures: Failure[], path: string, error: unknown) {
  failures.push({ path, reason: String(error) });
}

function buildRelations(
  repositoryName: string,
  indexed: IndexedModule[]
): { from: string; to: string; relationType: string }[] {
  return indexed.map((entry) => ({
    from: entry.path,
    to: repositoryName,
    relationType: "belongs_to",
  }));
}

function graphIsSettled(entityCount: number, expected: number): boolean {
  return entityCount >= expected;
}

function renderReport(
  repositoryName: string,
  indexed: IndexedModule[],
  failures: Failure[]
): string {
  const lines: string[] = [];
  lines.push("# Repository index report");
  lines.push("");
  lines.push(`Repository: ${repositoryName}`);
  lines.push("");
  lines.push("## Modules");
  for (const entry of indexed) {
    lines.push(`- ${entry.path} — ${entry.lines} lines`);
  }
  lines.push("");
  lines.push("## Failures");
  if (failures.length === 0) {
    lines.push("- none");
  } else {
    for (const failure of failures) {
      lines.push(`- ${failure.path}: ${failure.reason}`);
    }
  }
  return lines.join("\n");
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  const failures: Failure[] = [];
  const indexed: IndexedModule[] = [];

  const repository = await tools.memory.createEntities({
    entities: [{ name: input.root, entityType: "repository", observations: [] }],
  });

  const searchHits = await tools.fs.searchFiles({
    path: input.root,
    pattern: "*.ts",
  });
  const modulePaths = parseSearchHits(searchHits.content);
  const selectedPaths = takeFirst(modulePaths, input.maxModules);

  for (const path of selectedPaths) {
    try {
      const file = await tools.fs.readTextFile({ path });
      const entry = summarizeModule(path, file.content);
      await tools.memory.createEntities({
        entities: [
          { name: path, entityType: "module", observations: moduleObservations(entry) },
        ],
      });
      recordIndexed(indexed, entry);
    } catch (error) {
      recordFailure(failures, path, error);
    }
  }

  const relations = buildRelations(input.root, indexed);
  const createdRelations = await tools.memory.createRelations({ relations });

  const expectedEntities = 1 + indexed.length;
  let settleAttempts = 0;
  let settled = false;
  while (!settled && settleAttempts < 3) {
    settleAttempts += 1;
    const graph = await tools.memory.readGraph({});
    const complete = graphIsSettled(graph.entities.length, expectedEntities);
    settled = complete;
  }

  const report = renderReport(input.root, indexed, failures);
  const savedReport = await tools.fs.writeFile({
    path: `${input.root}/index-report.md`,
    content: report,
  });

  return {
    modulesIndexed: indexed.length,
    modulesFailed: failures.length,
    settleAttempts,
  };
}

import type { Tools } from "../generated/tools";

type ModuleGrade = {
  path: string;
  grade: string;
};

function parseModulePaths(searchOutput: string): string[] {
  return searchOutput
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
}

function takeFirst(paths: string[], limit: number): string[] {
  return paths.slice(0, Math.max(0, limit));
}

function extractSizeBytes(fileInfoText: string): number {
  const jsonMatch = fileInfoText.match(/"size"\s*:\s*(\d+)/);
  if (jsonMatch !== null) {
    return Number(jsonMatch[1]);
  }
  const looseMatch = fileInfoText.match(/[Ss]ize\s*[:=]\s*(\d+)/);
  if (looseMatch !== null) {
    return Number(looseMatch[1]);
  }
  return fileInfoText.length;
}

function gradeModule(sizeBytes: number, sourceText: string): string {
  if (sizeBytes > 200) {
    return "large";
  }
  if (sourceText.includes("/**")) {
    return "documented";
  }
  return "plain";
}

function recordGrade(grades: ModuleGrade[], path: string, grade: string) {
  grades.push({ path, grade });
}

function recordFailure(failures: string[], path: string, error: unknown) {
  failures.push(`${path}: ${String(error)}`);
}

function buildAuditReport(grades: ModuleGrade[], thoughtsRecorded: number): string {
  const lines: string[] = ["# Repository audit", "", "## module grades", ""];
  for (const entry of grades) {
    lines.push(`- ${entry.path}: ${entry.grade}`);
  }
  lines.push("", "## reasoning", "");
  lines.push(
    `Sequential-thinking audit completed: ${thoughtsRecorded} of 3 thoughts were taken and recorded.`
  );
  return lines.join("\n");
}

function countByGrade(grades: ModuleGrade[]): Record<string, number> {
  const counts: Record<string, number> = { large: 0, documented: 0, plain: 0 };
  for (const entry of grades) {
    counts[entry.grade] = (counts[entry.grade] ?? 0) + 1;
  }
  return counts;
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  const [sizes, tree, allowed] = await Promise.all([
    tools.fs.listDirectoryWithSizes({ path: input.root }),
    tools.fs.directoryTree({ path: input.root }),
    tools.fs.listAllowedDirectories({}),
  ]);

  const searchOutput = await tools.fs.searchFiles({
    path: input.root,
    pattern: "**/*.ts",
  });
  const foundModules = parseModulePaths(searchOutput.content);
  const selectedModules = takeFirst(foundModules, input.maxModules);

  const grades: ModuleGrade[] = [];
  const failures: string[] = [];

  for (const modulePath of selectedModules) {
    try {
      const info = await tools.fs.getFileInfo({ path: modulePath });
      const sizeBytes = extractSizeBytes(info.content);
      const source = await tools.fs.readTextFile({ path: modulePath });
      const grade = gradeModule(sizeBytes, source.content);
      recordGrade(grades, modulePath, grade);
    } catch (error) {
      recordFailure(failures, modulePath, error);
    }
  }

  const thoughtOne = await tools.reasoning.sequentialThinking({
    thought: `Audit scope for ${input.root}: the sized directory listing, the recursive tree, and the server's allowed directories were gathered in one parallel batch; next comes the TypeScript module sweep.`,
    thoughtNumber: 1,
    totalThoughts: 3,
    nextThoughtNeeded: true,
  });

  const thoughtTwo = await tools.reasoning.sequentialThinking({
    thought: `Module sweep: ${selectedModules.length} of ${foundModules.length} TypeScript modules were graded (capped at ${input.maxModules}); a module is large above 200 bytes, otherwise documented when its text contains a JSDoc block, otherwise plain.`,
    thoughtNumber: 2,
    totalThoughts: 3,
    nextThoughtNeeded: true,
  });

  const thoughtThree = await tools.reasoning.sequentialThinking({
    thought: `Wrap-up: every selected module carries exactly one grade, ${failures.length} unreadable module(s) were recorded and skipped instead of failing the run, and audit.md will list each grade plus this reasoning trail.`,
    thoughtNumber: 3,
    totalThoughts: 3,
    nextThoughtNeeded: false,
  });

  const thoughts = [thoughtOne, thoughtTwo, thoughtThree];

  const report = buildAuditReport(grades, thoughts.length);
  await tools.fs.writeFile({
    path: `${input.root}/audit.md`,
    content: report,
  });

  const gradeCounts = countByGrade(grades);

  return {
    gradeCounts,
    thoughtsRecorded: thoughts.length,
    failures,
  };
}

import type { Tools } from "../generated/tools";

interface BatchNote {
  path: string;
  text: string;
}

interface NoteFailure {
  path: string;
  reason: string;
}

/** Parses the newline-separated path list returned by fs.searchFiles. */
function parseFoundPaths(content: string): string[] {
  return content
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line !== "");
}

/** Splits the found notes into batches of at most batchSize paths. */
function chunkIntoBatches(paths: string[], batchSize: number): string[][] {
  const size = Math.max(1, Math.floor(batchSize));
  const batches: string[][] = [];
  for (let i = 0; i < paths.length; i += size) {
    batches.push(paths.slice(i, i + size));
  }
  return batches;
}

/**
 * Splits the combined output of one fs.readMultipleFiles call back into
 * per-note texts. The server formats each file as `<path>:\n<text>`,
 * separated by blank lines, so the known batch paths are used as markers.
 */
function splitBatchContent(content: string, paths: string[]): BatchNote[] {
  const notes: BatchNote[] = [];
  for (let i = 0; i < paths.length; i += 1) {
    const marker = `${paths[i]}:\n`;
    const start = content.indexOf(marker);
    if (start === -1) {
      continue;
    }
    const textStart = start + marker.length;
    let textEnd = content.length;
    if (i + 1 < paths.length) {
      const nextStart = content.indexOf(`${paths[i + 1]}:\n`, textStart);
      if (nextStart !== -1) {
        textEnd = nextStart;
      }
    }
    notes.push({
      path: paths[i],
      text: content.slice(textStart, textEnd).replace(/\s+$/, ""),
    });
  }
  return notes;
}

/** Prefixes a note with the migration marker; an empty note stays empty. */
function withMigrationMarker(text: string): string {
  if (text.trim() === "") {
    return "";
  }
  return `<!-- migrated -->\n${text}`;
}

/** Last segment of a path, used as the archived file name. */
function baseName(path: string): string {
  const parts = path.split("/");
  return parts[parts.length - 1];
}

/** Destination path for a note inside <root>/archive. */
function archivePathFor(root: string, originalPath: string): string {
  return `${root}/archive/${baseName(originalPath)}`;
}

/** Records a failed note so the run can carry on with the next one. */
function recordFailure(failures: NoteFailure[], path: string, error: unknown): void {
  failures.push({ path, reason: String(error) });
}

/** Renders the final migration-report.md contents. */
function buildReport(
  migrated: number,
  skipped: number,
  failures: NoteFailure[],
  abandoned: boolean
): string {
  const lines: string[] = [
    "# Migration report",
    "",
    `Migrated: ${migrated}`,
    `Skipped: ${skipped}`,
    `Failed: ${failures.length}`,
    `Abandoned: ${abandoned ? "yes" : "no"}`,
  ];
  if (failures.length > 0) {
    lines.push("", "## Failures");
    for (const failure of failures) {
      lines.push(`- ${failure.path}: ${failure.reason}`);
    }
  }
  return lines.join("\n");
}

export default async function flow(
  input: { root: string; batchSize: number; maxFailures: number },
  tools: Tools
) {
  // 1. Make sure the destination exists before anything is written.
  await tools.fs.createDirectory({ path: `${input.root}/archive` });

  // 2. Find every markdown note under the root.
  const found = await tools.fs.searchFiles({ path: input.root, pattern: "**/*.md" });
  const notePaths = parseFoundPaths(found.content);

  if (notePaths.length === 0) {
    await tools.fs.writeFile({ path: `${input.root}/migration-report.md`, content: "" });
    return { migrated: 0, skipped: 0, failed: 0, abandoned: false };
  }

  const batches = chunkIntoBatches(notePaths, input.batchSize);

  let migrated = 0;
  let skipped = 0;
  let abandoned = false;
  const failures: NoteFailure[] = [];

  // 3. Loop over batches; each batch is read with a single call.
  for (const batch of batches) {
    if (abandoned) {
      break;
    }

    let raw: string | null = null;
    try {
      const batchRead = await tools.fs.readMultipleFiles({ paths: batch });
      raw = batchRead.content;
    } catch (error) {
      for (const path of batch) {
        recordFailure(failures, path, error);
      }
    }

    if (raw === null) {
      if (failures.length > input.maxFailures) {
        abandoned = true;
        break;
      }
      continue;
    }

    const notes = splitBatchContent(raw, batch);

    // Handle each note in the batch one at a time.
    for (const note of notes) {
      const transformed = withMigrationMarker(note.text);

      // 4. An empty note counts as neither a success nor a failure.
      if (transformed === "") {
        skipped += 1;
        continue;
      }

      // 5. Archive under the original file name.
      const destination = archivePathFor(input.root, note.path);

      try {
        await tools.fs.writeFile({ path: destination, content: transformed });
      } catch (error) {
        // 6. Record the failure and carry on with the next note.
        recordFailure(failures, note.path, error);
        if (failures.length > input.maxFailures) {
          abandoned = true;
          break;
        }
        continue;
      }

      // 7. Record the migrated note in the knowledge graph.
      await tools.memory.createEntities({
        entities: [
          { name: note.path, entityType: "note", observations: [destination] },
        ],
      });
      migrated += 1;
    }
  }

  // 8. Write the report and return the outcome.
  const report = buildReport(migrated, skipped, failures, abandoned);
  await tools.fs.writeFile({ path: `${input.root}/migration-report.md`, content: report });

  return { migrated, skipped, failed: failures.length, abandoned };
}

import type { Tools } from "../generated/tools";

type IndexedModule = { path: string; lines: number };

function parseFoundPaths(listing: string): string[] {
  return listing
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
}

function selectModules(paths: string[], maxModules: number): string[] {
  if (maxModules <= 0) {
    return [];
  }
  return paths.slice(0, maxModules);
}

function countLines(source: string): number {
  const normalized = source.replace(/\r\n/g, "\n");
  const lines = normalized.split("\n");
  if (lines.length > 0 && lines[lines.length - 1] === "") {
    lines.pop();
  }
  return lines.length;
}

function extractExportedNames(source: string): string[] {
  const names: string[] = [];
  const pattern =
    /export\s+(?:default\s+)?(?:async\s+)?(?:interface|type|class|enum|function|const|let|var)\s+([A-Za-z_$][\w$]*)/g;
  let match = pattern.exec(source);
  while (match !== null) {
    names.push(match[1]);
    match = pattern.exec(source);
  }
  return names;
}

function moduleObservations(lineCount: number, exportedNames: string[]): string[] {
  return [
    `line count: ${lineCount}`,
    `exports: ${exportedNames.join(", ")}`,
  ];
}

function recordIndexedModule(indexed: IndexedModule[], path: string, lines: number) {
  indexed.push({ path, lines });
}

function recordFailure(failures: string[], key: string, error: unknown) {
  failures.push(`${key}: ${String(error)}`);
}

function moduleRelations(modules: IndexedModule[], repositoryName: string) {
  return modules.map((mod) => ({
    from: repositoryName,
    to: mod.path,
    relationType: "contains",
  }));
}

function graphIsSettled(entityCount: number, expectedCount: number): boolean {
  return entityCount >= expectedCount;
}

function buildReport(indexed: IndexedModule[], failures: string[]): string {
  const lines: string[] = [];
  lines.push("# Index report");
  lines.push("");
  lines.push(`Modules indexed: ${indexed.length}`);
  lines.push("");
  for (const mod of indexed) {
    lines.push(`- ${mod.path}: ${mod.lines} lines`);
  }
  lines.push("");
  lines.push(`Failures: ${failures.length}`);
  for (const failure of failures) {
    lines.push(`- ${failure}`);
  }
  return lines.join("\n");
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  const failures: string[] = [];
  const indexedModules: IndexedModule[] = [];

  const repositoryCreated = await tools.memory.createEntities({
    entities: [{ name: input.root, entityType: "repository", observations: [] }],
  });

  const searchResults = await tools.fs.searchFiles({ path: input.root, pattern: "*.ts" });
  const foundPaths = parseFoundPaths(searchResults.content);
  const modulePaths = selectModules(foundPaths, input.maxModules);

  for (const filePath of modulePaths) {
    try {
      const fileContent = await tools.fs.readTextFile({ path: filePath });
      const lineCount = countLines(fileContent.content);
      const exportedNames = extractExportedNames(fileContent.content);
      const observations = moduleObservations(lineCount, exportedNames);
      const moduleCreated = await tools.memory.createEntities({
        entities: [{ name: filePath, entityType: "module", observations }],
      });
      recordIndexedModule(indexedModules, filePath, lineCount);
    } catch (error) {
      recordFailure(failures, filePath, error);
    }
  }

  const relations = moduleRelations(indexedModules, input.root);
  const relationsCreated = await tools.memory.createRelations({ relations });

  const expectedEntities = 1 + indexedModules.length;
  let settleAttempts = 0;
  let graphSettled = false;
  let entityCount = 0;

  while (!graphSettled && settleAttempts < 3) {
    settleAttempts += 1;
    const graph = await tools.memory.readGraph({});
    entityCount = graph.entities.length;
    const enoughEntities = graphIsSettled(entityCount, expectedEntities);
    graphSettled = enoughEntities;
  }

  const report = buildReport(indexedModules, failures);
  const reportWritten = await tools.fs.writeFile({
    path: `${input.root}/index-report.md`,
    content: report,
  });

  return {
    modulesIndexed: indexedModules.length,
    modulesFailed: failures.length,
    settleAttempts,
  };
}

import type { Tools } from "../generated/tools";

type Grade = "large" | "documented" | "plain";

interface AuditedModule {
  path: string;
  sizeBytes: number;
  grade: Grade;
}

interface SequentialThoughtResult {
  thoughtNumber: number;
  totalThoughts: number;
  nextThoughtNeeded: boolean;
  branches: string[];
  thoughtHistoryLength: number;
}

interface ScopeSnapshot {
  listing: string;
  tree: string;
  allowedDirectories: string;
}

function parseModuleList(raw: string): string[] {
  const trimmed = raw.trim();
  if (trimmed.startsWith("[")) {
    try {
      const parsed: unknown = JSON.parse(trimmed);
      if (Array.isArray(parsed)) {
        return parsed.filter(
          (entry): entry is string =>
            typeof entry === "string" && entry.endsWith(".ts")
        );
      }
    } catch {
      // fall through to line-based parsing
    }
  }
  return trimmed
    .split("\n")
    .map((line) => line.replace(/^\[[^\]]*\]/, "").replace(/^[-*]\s*/, "").trim())
    .filter((line) => line.length > 0 && line.endsWith(".ts"));
}

function limitToMax(modulePaths: string[], max: number): string[] {
  return modulePaths.slice(0, Math.max(0, max));
}

function parseSizeBytes(infoRaw: string): number {
  const labelled = infoRaw.match(/size\W{0,3}(\d+)/i);
  if (labelled) {
    return Number(labelled[1]);
  }
  const fallback = infoRaw.match(/\b\d{2,}\b/);
  return fallback ? Number(fallback[0]) : 0;
}

function gradeModule(sizeBytes: number, sourceText: string): Grade {
  if (sizeBytes > 200) {
    return "large";
  }
  if (sourceText.includes("/**")) {
    return "documented";
  }
  return "plain";
}

function recordModule(
  audited: AuditedModule[],
  path: string,
  sizeBytes: number,
  grade: Grade
): void {
  audited.push({ path, sizeBytes, grade });
}

function recordFailure(failures: string[], key: string, error: unknown): void {
  failures.push(`${key}: ${String(error)}`);
}

function collectThought(
  collected: SequentialThoughtResult[],
  result: SequentialThoughtResult
): void {
  collected.push(result);
}

function summarizeThought(result: SequentialThoughtResult): string {
  return `- thought ${result.thoughtNumber}/${result.totalThoughts} — nextThoughtNeeded: ${result.nextThoughtNeeded}`;
}

function countGrades(audited: AuditedModule[]): Record<Grade, number> {
  const counts: Record<Grade, number> = { large: 0, documented: 0, plain: 0 };
  for (const entry of audited) {
    counts[entry.grade] += 1;
  }
  return counts;
}

function buildAuditReport(
  audited: AuditedModule[],
  failures: string[],
  thoughts: SequentialThoughtResult[],
  scope: ScopeSnapshot
): string {
  const gradeLines = audited
    .map((entry) => `- \`${entry.path}\` — **${entry.grade}** (${entry.sizeBytes} bytes)`)
    .join("\n");
  const failureLines =
    failures.length > 0
      ? failures.map((failure) => `- ${failure}`).join("\n")
      : "- none";
  const thoughtLines = thoughts.map(summarizeThought).join("\n");

  return [
    "# Repository Audit",
    "",
    "## module grades",
    "",
    gradeLines.length > 0 ? gradeLines : "- no TypeScript modules found",
    "",
    "## unreadable modules",
    "",
    failureLines,
    "",
    "## reasoning",
    "",
    `${thoughts.length} sequential thoughts were taken (numbered 1–3 out of 3); after the third, no further thought was needed.`,
    "",
    thoughtLines,
    "",
    "## scope",
    "",
    "### directory listing with sizes",
    "",
    "```",
    scope.listing.trim(),
    "```",
    "",
    "### directory tree",
    "",
    "```",
    scope.tree.trim(),
    "```",
    "",
    "### allowed directories",
    "",
    "```",
    scope.allowedDirectories.trim(),
    "```",
    ""
  ].join("\n");
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  // Snapshot the root: listing, tree and sandbox limits — none waits for another.
  const [listing, tree, allowedDirs] = await Promise.all([
    tools.fs.listDirectoryWithSizes({ path: input.root }),
    tools.fs.directoryTree({ path: input.root }),
    tools.fs.listAllowedDirectories({})
  ]);

  // Find candidate TypeScript modules and cap the workload at maxModules.
  const searchHits = await tools.fs.searchFiles({ path: input.root, pattern: "*.ts" });
  const allModules = parseModuleList(searchHits.content);
  const selectedModules = limitToMax(allModules, input.maxModules);

  const audited: AuditedModule[] = [];
  const failures: string[] = [];

  for (const modulePath of selectedModules) {
    try {
      const info = await tools.fs.getFileInfo({ path: modulePath });
      const source = await tools.fs.readTextFile({ path: modulePath });
      const sizeBytes = parseSizeBytes(info.content);
      const grade = gradeModule(sizeBytes, source.content);
      recordModule(audited, modulePath, sizeBytes, grade);
    } catch (error) {
      recordFailure(failures, modulePath, error);
    }
  }

  // Think the audit through in exactly three numbered thoughts.
  const thoughtOne = await tools.reasoning.sequentialThinking({
    thought: `Inventory: graded ${audited.length} of ${allModules.length} TypeScript module(s) under ${input.root}; ${failures.length} module(s) could not be read and were skipped.`,
    nextThoughtNeeded: true,
    thoughtNumber: 1,
    totalThoughts: 3
  });
  const midCounts = countGrades(audited);
  const thoughtTwo = await tools.reasoning.sequentialThinking({
    thought: `Coverage check: ${midCounts.large} large, ${midCounts.documented} documented, ${midCounts.plain} plain — plain modules lack a /** doc block and may need documentation before release.`,
    nextThoughtNeeded: true,
    thoughtNumber: 2,
    totalThoughts: 3
  });
  const thoughtThree = await tools.reasoning.sequentialThinking({
    thought: `Verification: ${audited.length} module grade(s) and ${failures.length} recorded read failure(s) will be written to audit.md; the three-thought review is complete.`,
    nextThoughtNeeded: false,
    thoughtNumber: 3,
    totalThoughts: 3
  });

  const thoughts: SequentialThoughtResult[] = [];
  collectThought(thoughts, thoughtOne);
  collectThought(thoughts, thoughtTwo);
  collectThought(thoughts, thoughtThree);

  const counts = countGrades(audited);
  const report = buildAuditReport(audited, failures, thoughts, {
    listing: listing.content,
    tree: tree.content,
    allowedDirectories: allowedDirs.content
  });
  const written = await tools.fs.writeFile({
    path: `${input.root}/audit.md`,
    content: report
  });

  return {
    counts,
    thoughtsRecorded: thoughts.length,
    modulesAudited: audited.length,
    unreadableModules: failures,
    writeConfirmation: written.content
  };
}

import type { Tools } from "../generated/tools";

// --- Types ---

interface MigrationFailure {
  path: string;
  reason: string;
}

// One note as it comes back from a batch read: either its text, or why it failed.
interface ParsedNote {
  path: string;
  text: string;
  error: string | null;
}

// --- Helpers (each becomes a readable node in the graph) ---

function baseName(path: string): string {
  const segments = path.split("/");
  return segments[segments.length - 1];
}

function archivePathFor(root: string, originalPath: string): string {
  return `${root}/archive/${baseName(originalPath)}`;
}

function reportPathFor(root: string): string {
  return `${root}/migration-report.md`;
}

// searchFiles returns a plain list of matching paths, one per line.
function parseMarkdownPaths(searchResult: string): string[] {
  return searchResult
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
}

function chunk(items: string[], size: number): string[][] {
  const effectiveSize = Math.max(1, Math.floor(size));
  const chunks: string[][] = [];
  for (let index = 0; index < items.length; index += effectiveSize) {
    chunks.push(items.slice(index, index + effectiveSize));
  }
  return chunks;
}

// readMultipleFiles returns one combined string where every file appears as
// `<path>:<text>` and sections are separated by `\n---\n`. Failed reads come
// back as `<path>:Error: ...`. Rebuild one entry per requested path so a file
// the reader could not open still surfaces as that note's own failure.
function parseBatchNotes(requestedPaths: string[], raw: string): ParsedNote[] {
  const textByPath = new Map<string, string>();

  for (const section of raw.split("\n---\n")) {
    const trimmedSection = section.trim();
    if (trimmedSection.length === 0) {
      continue;
    }
    const splitAt = trimmedSection.indexOf(":");
    if (splitAt < 1) {
      continue;
    }
    const path = trimmedSection.slice(0, splitAt).trim();
    const text = trimmedSection.slice(splitAt + 1).trim();
    if (path.length > 0) {
      textByPath.set(path, text);
    }
  }

  return requestedPaths.map((path) => {
    const text = textByPath.get(path);
    if (text === undefined) {
      return { path, text: "", error: "the batch read did not return this file" };
    }
    if (text.startsWith("Error:")) {
      return { path, text: "", error: text };
    }
    return { path, text, error: null };
  });
}

// Prefixes the note with the migration marker; a blank note transforms to empty.
function transformNote(text: string): string {
  if (text.trim().length === 0) {
    return "";
  }
  return `<!-- migrated -->\n${text}`;
}

function describeReason(reason: unknown): string {
  return reason instanceof Error ? reason.message : String(reason);
}

function recordFailure(failures: MigrationFailure[], path: string, reason: unknown): void {
  failures.push({ path, reason: describeReason(reason) });
}

function formatReport(
  migrated: number,
  skipped: number,
  failed: number,
  abandoned: boolean,
  failures: MigrationFailure[]
): string {
  const lines: string[] = [
    "# Markdown migration report",
    "",
    `- Migrated: ${migrated}`,
    `- Skipped (empty): ${skipped}`,
    `- Failed: ${failed}`,
    `- Abandoned: ${abandoned ? "yes" : "no"}`,
    "",
    "## Failures",
    ""
  ];
  if (failures.length === 0) {
    lines.push("None");
  } else {
    for (const failure of failures) {
      lines.push(`- ${failure.path}: ${failure.reason}`);
    }
  }
  return `${lines.join("\n")}\n`;
}

// --- Flow ---

export default async function flow(
  input: { root: string; batchSize: number; maxFailures: number },
  tools: Tools
) {
  // 1. The destination exists before anything is written.
  await tools.fs.createDirectory({ path: `${input.root}/archive` });

  // 2. Find every markdown note under the root.
  const searchResult = await tools.fs.searchFiles({ path: input.root, pattern: "**/*.md" });
  const notePaths = parseMarkdownPaths(searchResult.content);

  let migrated = 0;
  let skipped = 0;
  let abandoned = false;
  const failures: MigrationFailure[] = [];

  if (notePaths.length === 0) {
    await tools.fs.writeFile({ path: reportPathFor(input.root), content: "" });
    return { migrated: 0, skipped: 0, failed: 0, abandoned: false };
  }

  // 3. Batches of batchSize: one bulk read per batch, one pass per note inside.
  const batches = chunk(notePaths, input.batchSize);

  for (const batch of batches) {
    let rawContents = "";
    try {
      const fetched = await tools.fs.readMultipleFiles({ paths: batch });
      rawContents = fetched.content;
    } catch (error) {
      // The whole batch read blew up: every note in it is a failure.
      for (const path of batch) {
        recordFailure(failures, path, error);
        if (failures.length > input.maxFailures) {
          abandoned = true;
          break;
        }
      }
      if (abandoned) {
        break;
      }
      continue;
    }

    const notes = parseBatchNotes(batch, rawContents);

    for (const note of notes) {
      if (note.error !== null) {
        recordFailure(failures, note.path, note.error);
        if (failures.length > input.maxFailures) {
          abandoned = true;
          break;
        }
        continue;
      }

      // 4. Empty notes are skipped without counting as success or failure.
      const transformed = transformNote(note.text);
      if (transformed === "") {
        skipped += 1;
        continue;
      }

      // 5. The archive copy keeps its original file name.
      const destination = archivePathFor(input.root, note.path);

      try {
        await tools.fs.writeFile({ path: destination, content: transformed });
      } catch (error) {
        recordFailure(failures, note.path, error);
        if (failures.length > input.maxFailures) {
          abandoned = true;
          break;
        }
        continue;
      }

      // 7. Record the successfully migrated note in the knowledge graph.
      await tools.memory.createEntities({
        entities: [{ name: note.path, entityType: "note", observations: [destination] }]
      });

      migrated += 1;
    }

    if (abandoned) {
      break;
    }
  }

  // 8. Final report and result.
  const report = formatReport(migrated, skipped, failures.length, abandoned, failures);
  await tools.fs.writeFile({ path: reportPathFor(input.root), content: report });

  return { migrated, skipped, failed: failures.length, abandoned };
}
